// ======================================================
// AI HR ATS - n8n Code Node
// Converts AI Agent output into structured ATS fields
// ======================================================


// ------------------------------------------------------
// 1. GET AI AGENT OUTPUT
// ------------------------------------------------------

const text = String(
  $json.output ??
  $json.text ??
  $json.response ??
  ""
);


// Stop the workflow if no AI output was received
if (!text.trim()) {
  throw new Error(
    "AI Agent output is empty. Check the connection between the AI Agent and Code node."
  );
}


// ------------------------------------------------------
// 2. HELPER FUNCTIONS
// ------------------------------------------------------

// Escape text before using it inside RegExp
function escapeRegex(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}


// Clean Markdown / formatting from extracted text
function cleanText(value) {

  if (!value) {
    return "";
  }

  return String(value)

    // Remove bold markdown
    .replace(/\*\*/g, "")

    // Remove heading markers
    .replace(/^#+\s*/gm, "")

    // Remove bullet characters
    .replace(/^\s*[-•]\s*/gm, "")

    // Remove excessive new lines
    .replace(/\r/g, "")
    .replace(/\n+/g, " ")

    // Remove excessive spaces
    .replace(/\s+/g, " ")

    .trim();
}


// Extract a complete section between headings
function getSection(startLabel, endLabels = []) {

  const startPattern = new RegExp(
    `(?:\\*\\*)?${escapeRegex(startLabel)}(?:\\*\\*)?\\s*:?\\s*`,
    "i"
  );

  const startMatch = startPattern.exec(text);

  if (!startMatch) {
    return "";
  }

  const startIndex =
    startMatch.index + startMatch[0].length;

  let endIndex = text.length;


  for (const endLabel of endLabels) {

    const remainingText =
      text.slice(startIndex);

    const endPattern = new RegExp(
      `(?:\\*\\*)?${escapeRegex(endLabel)}(?:\\*\\*)?\\s*:?`,
      "i"
    );

    const endMatch =
      endPattern.exec(remainingText);


    if (endMatch) {

      const possibleEnd =
        startIndex + endMatch.index;

      if (possibleEnd < endIndex) {
        endIndex = possibleEnd;
      }
    }
  }


  return cleanText(
    text.slice(startIndex, endIndex)
  );
}


// ------------------------------------------------------
// 3. EXTRACT SCORE
// ------------------------------------------------------

let score = null;


// Format:
// Candidate Score: 83 / 100
let scoreMatch = text.match(
  /Candidate\s*Score\s*:?\s*\*{0,2}\s*(\d{1,3})\s*\/\s*100/i
);


// Format:
// Score: 83 / 100
if (!scoreMatch) {

  scoreMatch = text.match(
    /\bScore\s*:?\s*\*{0,2}\s*(\d{1,3})\s*\/\s*100/i
  );

}


// Format:
// Candidate Score: 83
if (!scoreMatch) {

  scoreMatch = text.match(
    /Candidate\s*Score\s*:?\s*\*{0,2}\s*(\d{1,3})\b/i
  );

}


// General fallback:
// 83 / 100
if (!scoreMatch) {

  scoreMatch = text.match(
    /\b(\d{1,3})\s*\/\s*100\b/
  );

}


if (scoreMatch) {

  score = Number(scoreMatch[1]);

}


// Validate score
if (
  score === null ||
  Number.isNaN(score) ||
  score < 0 ||
  score > 100
) {

  throw new Error(
    "Could not extract a valid candidate score from AI Agent output.\n\nAI OUTPUT:\n" +
    text
  );

}


// ------------------------------------------------------
// 4. STRONG POINTS
// ------------------------------------------------------

const strong_point = getSection(

  "Strong Points",

  [
    "Weak Points",
    "Skills Match",
    "Experience Match",
    "Education Match",
    "Job Fit",
    "Recruitment Decision",
    "Short Reasoning"
  ]

);


// ------------------------------------------------------
// 5. WEAK POINTS
// ------------------------------------------------------

const weak_point = getSection(

  "Weak Points",

  [
    "Skills Match",
    "Experience Match",
    "Education Match",
    "Job Fit",
    "Recruitment Decision",
    "Short Reasoning"
  ]

);


// ------------------------------------------------------
// 6. SKILLS MATCH
// ------------------------------------------------------

const skills_match = getSection(

  "Skills Match",

  [
    "Experience Match",
    "Education Match",
    "Job Fit",
    "Recruitment Decision",
    "Short Reasoning"
  ]

);


// ------------------------------------------------------
// 7. EXPERIENCE MATCH
// ------------------------------------------------------

const experience_match = getSection(

  "Experience Match",

  [
    "Education Match",
    "Job Fit",
    "Recruitment Decision",
    "Short Reasoning"
  ]

);


// ------------------------------------------------------
// 8. EDUCATION MATCH
// ------------------------------------------------------

const education_match = getSection(

  "Education Match",

  [
    "Job Fit",
    "Recruitment Decision",
    "Short Reasoning"
  ]

);


// ------------------------------------------------------
// 9. JOB FIT
// ------------------------------------------------------

let fit_for_job = getSection(

  "Job Fit",

  [
    "Recruitment Decision",
    "Short Reasoning"
  ]

);


// ------------------------------------------------------
// 10. RECRUITMENT DECISION
// ------------------------------------------------------

let recommendation = getSection(

  "Recruitment Decision",

  [
    "Short Reasoning"
  ]

);


// ------------------------------------------------------
// 11. SHORT REASONING
// ------------------------------------------------------

const short_reasoning = getSection(

  "Short Reasoning",

  []

);


// ------------------------------------------------------
// 12. NORMALIZE JOB FIT
// ------------------------------------------------------

let fit_category = "";

const fitText =
  fit_for_job.toLowerCase();


if (fitText.includes("strong fit")) {

  fit_category = "Strong Fit";

}
else if (fitText.includes("good fit")) {

  fit_category = "Good Fit";

}
else if (fitText.includes("partial fit")) {

  fit_category = "Partial Fit";

}
else if (fitText.includes("weak fit")) {

  fit_category = "Weak Fit";

}
else if (fitText.includes("not a fit")) {

  fit_category = "Not a Fit";

}


// If AI forgot Job Fit, calculate from score
if (!fit_category) {

  if (score >= 90) {

    fit_category = "Strong Fit";

  }
  else if (score >= 75) {

    fit_category = "Good Fit";

  }
  else if (score >= 60) {

    fit_category = "Partial Fit";

  }
  else if (score >= 40) {

    fit_category = "Weak Fit";

  }
  else {

    fit_category = "Not a Fit";

  }

}


// ------------------------------------------------------
// 13. NORMALIZE RECOMMENDATION
// ------------------------------------------------------

let recruitment_decision = "";

const recommendationText =
  recommendation.toLowerCase();


if (recommendationText.includes("shortlist")) {

  recruitment_decision = "Shortlist";

}
else if (recommendationText.includes("consider")) {

  recruitment_decision = "Consider";

}
else if (recommendationText.includes("reject")) {

  recruitment_decision = "Reject";

}


// Calculate decision if AI omitted it
if (!recruitment_decision) {

  if (score >= 75) {

    recruitment_decision = "Shortlist";

  }
  else if (score >= 60) {

    recruitment_decision = "Consider";

  }
  else {

    recruitment_decision = "Reject";

  }

}


// ------------------------------------------------------
// 14. GET GOOGLE SHEETS ROW NUMBER
// ------------------------------------------------------

let row_number = null;


// First try current item
if ($json.row_number) {

  row_number = $json.row_number;

}


// Otherwise get it from original Google Sheets node
if (!row_number) {

  try {

    row_number =
      $('Get row(s) in sheet').item.json.row_number;

  }
  catch (error) {

    row_number = null;

  }

}


// ------------------------------------------------------
// 15. FINAL ATS OUTPUT
// ------------------------------------------------------

return [
  {
    json: {

      row_number: row_number,

      score: score,

      strong_point:
        strong_point || "Not enough information provided.",

      weak_point:
        weak_point || "No major weaknesses identified.",

      skills_match:
        skills_match || "Not enough information provided.",

      experience_match:
        experience_match || "Not enough information provided.",

      education_match:
        education_match || "Not enough information provided.",

      fit_for_job:
        fit_category,

      recommendation:
        recruitment_decision,

      short_reasoning:
        short_reasoning || "Not enough information provided."

    }
  }
];
